import { objectives, type CoverageState } from "./guide.ts";
import { enemyEncounters, enemyRecords, type EnemyLootSlot, type EnemyTableSlot } from "./enemies.ts";

export type GameItemCategory = "consumable" | "equipment" | "key-item";

export type ItemAcquisitionMethod =
  | "starting-inventory"
  | "chest"
  | "hidden-pickup"
  | "fixed-pickup"
  | "moogle-shop"
  | "shop"
  | "mogshop"
  | "mognet-reward"
  | "quest-reward"
  | "point-redemption"
  | "steal"
  | "drop"
  | "ability-extract"
  | "chocograph"
  | "auction"
  | "starting-equipment"
  | "synthesis";

export type ItemAcquisitionAvailability = "single-use" | "one-time-encounter" | "limited-window" | "conditional" | "repeatable" | "window-unverified";

export type ItemCost = {
  currency: "gil";
  amount: number;
  bundleId?: string;
};

export type GameItem = {
  id: string;
  name: string;
  category: GameItemCategory;
  sourceIds: string[];
  verification: CoverageState;
};

export type ItemAcquisitionPath = {
  id: string;
  itemId: string;
  chapterId: string;
  method: ItemAcquisitionMethod;
  quantity: number;
  availability: ItemAcquisitionAvailability;
  shopId?: string;
  shopName?: string;
  recipeId?: string;
  recommendedBeforeChapterId?: string;
  conditions?: string;
  notes?: string;
  cost?: ItemCost;
  walkthroughObjectiveIds?: string[];
  enemyId?: string;
  enemyLootSlot?: EnemyTableSlot;
  encounterIds?: string[];
  sourceIds: string[];
};

export type ItemInventoryTarget = {
  id: string;
  itemId: string;
  chapterId: string;
  targetQuantity: number;
  basis: "route-need" | "end-inventory" | "purchase-recommendation" | "checkpoint-total" | "buy-column-total";
  interpretation: string;
  sourceIds: string[];
};

export type EquipmentAbilityClaim = {
  id: string;
  itemId: string;
  abilityName: string;
  verification: CoverageState;
  sourceIds: string[];
};

