const zornThornShopRecoveryPath = (route: {
  id: string;
  itemSlug: string;
  itemName: string;
  chapterId: string;
  shopId: string;
  shopName: string;
  price: number;
  availability: ItemAcquisitionAvailability;
  locationSourceIds: string[];
  details: string;
  recommendedBeforeChapterId?: string;
  walkthroughObjectiveIds?: string[];
}): ItemAcquisitionPath => {
  const isFossilRooShop = route.shopId === "fossil-roo.treasure-hunter-shop";
  const isStardustRod = route.itemSlug === "stardust-rod";
  const stardustRodPriceNote = isStardustRod
    ? " Price discrepancy: GameFAQs Shops and Caves of Narshe list 750 Gil, while GameFAQs Items, the older GameFAQs Shop Lists, and RPGClassics Shops list 760 Gil; this shop path uses the direct GameFAQs Shops-table price."
    : "";
  return {
    id: route.id,
    itemId: `game-item.${route.itemSlug}`,
    chapterId: route.chapterId,
    method: "shop",
    quantity: 1,
    availability: route.availability,
    shopId: route.shopId,
    shopName: route.shopName,
    ...(route.recommendedBeforeChapterId ? { recommendedBeforeChapterId: route.recommendedBeforeChapterId } : {}),
    ...(route.walkthroughObjectiveIds
      ? { walkthroughObjectiveIds: route.walkthroughObjectiveIds }
      : isFossilRooShop
        ? { walkthroughObjectiveIds: ["disc-2.journey-to-outer-continent.treasure-sweep"] }
        : {}),
    conditions: `GameFAQs lists ${route.itemName} for ${route.price.toLocaleString("en-US")} Gil in ${route.shopName}. ${isFossilRooShop ? fossilRooShopWindowNote : route.details}${stardustRodPriceNote}`,
    cost: { currency: "gil", amount: route.price },
    sourceIds: [
      "gamefaqs-items-71891",
      "gamefaqs-shops-71891",
      ...route.locationSourceIds,
      ...(isStardustRod ? ["cavesofnarshe-ff9-rods", "gamefaqs-shop-lists-9772", "rpgclassics-shops"] : []),
      ...(isFossilRooShop ? fossilRooShopAccessSourceIds : []),
    ],
  };
};

