const moorockCommonShopSources = ["gamefaqs-shops-71891", "rpgclassics-shops", "elitegrindlab-bran-bal", "ffwiki-shops"];

const moorockProductSources = (product: MoorockProduct): string[] => {
  if (product.sourceGroup === "dagger") {
    return ["rpgclassics-shops", "elitegrindlab-bran-bal", "ffwiki-shops", "ff9-irodori-shops"];
  }
  if (product.sourceGroup === "magic-tag") return ["gamefaqs-shops-71891", "ffwiki-shops"];
  if (product.sourceGroup === "supply") return moorockCommonShopSources;
  return [...moorockCommonShopSources, "ff9-irodori-shops"];
};

const moorockSourceConflict = (product: MoorockProduct): string | undefined => {
  if (product.slug === "dagger") {
    return "GameFAQs' Shops FAQ omits Dagger from its Bran Bal stock table; RPGClassics, EliteGrindLab, and Final Fantasy Wiki include it for 320 Gil.";
  }
  if (product.slug === "magic-tag") {
    return "GameFAQs' Shops FAQ and Final Fantasy Wiki list Magic Tag for 100 Gil; RPGClassics and EliteGrindLab omit it from their Bran Bal counter lists.";
  }
  if (product.slug === "zorlin-shape") {
    return "Use the corroborated 6,000-Gil purchase price. GameFAQs' Shops table lists 2,300 Gil, conflicting with its item reference and the independent RPGClassics, Game8, EliteGrindLab, and Final Fantasy Wiki references.";
  }
  return undefined;
};

const makeMoorockMogshopPaths = (location: MoorockShopLocation): ItemAcquisitionPath[] =>
  moorockMogshopProducts.map((product) => {
    const isBranBal = location === "bran-bal";
    const locationNote = isBranBal
      ? "Buy it in Moorock's Bran Bal Mogshop before following Mikoto through the green gate. If you skip this stop, the same inventory is available from Moorock again in the Pandemonium Hall after the three forced fights."
      : "Moorock's Pandemonium Hall Mogshop has the same inventory as Bran Bal after the party regroups from the three forced fights. This is the final documented shop window before continuing into the Maze.";
    const sourceIds = moorockProductSources(product);
    if (product.slug === "zorlin-shape") sourceIds.push("gamefaqs-items-71891", "game8-zorlin-shape");
    if (!isBranBal) sourceIds.push("gamefaqs-portal-to-another-world-71891");
    const conflict = moorockSourceConflict(product);
    return {
      id: "item-path.disc-3.portal-to-another-world." + product.slug + "-" + location + "-mogshop",
      itemId: product.itemId,
      chapterId: "disc-3.portal-to-another-world",
      method: "mogshop",
      quantity: 1,
      availability: "limited-window",
      shopId: isBranBal ? "bran-bal.mogshop" : "pandemonium.moorock",
      shopName: isBranBal ? "Moorock's Mogshop (Bran Bal)" : "Moorock's Mogshop (Pandemonium Hall)",
      conditions: [locationNote, conflict].filter(Boolean).join(" "),
      cost: { currency: "gil", amount: product.price },
      walkthroughObjectiveIds: ["disc-3.portal-to-another-world.moorock-shop-review"],
      sourceIds,
    };
  });

